/**
 * QuoteBuilder -> stargtm /generate
 * Does NOT recalculate finance - UI Quote Sheet is the source of truth.
 * Finance values are passed through, never invented.
 */
const raw = $json.body || $json;
const lead = raw.nexusLead || raw.lead || {};
const uiLead = raw.lead || {};
const fin = raw.financials || {};
const form = raw.form || raw;

const upgradeIdMap = {
  'Live DJ': 'live_dj', Saxophonist: 'saxophonist', Karaoke: 'karaoke',
  'Photo Booth': 'photo_booth', 'Close-up Magician': 'close_up_magician',
  'Close up Magician': 'close_up_magician', 'Branded Vessel Flag': 'branded_vessel_flag',
  'Acoustic Artist': 'acoustic_artist', 'Jazz and Sax Duo': 'jazz_sax_duo',
  'Additional Hour on Board': 'extra_hour', 'Casino Table with Croupier': 'casino_table',
  'Social Media Highlight Reel': 'social_highlight_reel', 'Mingling Tour Guide': 'mingling_guide',
  'Bespoke Logo Bunting': 'logo_bunting', 'Unlimited Drinks (4 hrs)': 'unlimited_drinks',
  'Unlimited Drinks': 'unlimited_drinks', 'Drink Tokens': 'drink_tokens',
  'Street Food Upgrade': 'street_food_upgrade',
};

function addIfPresent(obj, key, value) {
  if (value !== undefined && value !== null && String(value).trim() !== '') obj[key] = String(value);
}
function money(n) {
  const v = Number(n);
  if (!Number.isFinite(v)) return 0;
  return Math.round((v + Number.EPSILON) * 100) / 100;
}
function mapUpgrades(selected) {
  return (Array.isArray(selected) ? selected : [])
    .map((u) => {
      if (typeof u !== 'string') return null;
      if (upgradeIdMap[u]) return upgradeIdMap[u];
      if (u.includes('_')) return u;
      return null;
    })
    .filter(Boolean);
}

const prebuilt = raw.calculations || {};
const packageCost = money(prebuilt.package_cost ?? fin.costToClient ?? fin.package_cost ?? 0);
const vat = money(prebuilt.vat ?? fin.vat ?? 0);
const grandTotal = money(prebuilt.grand_total ?? fin.grandTotal ?? fin.grand ?? (packageCost + vat));
const guests = Number(prebuilt.guests ?? form.guestCount ?? raw.guestCount) || 0;
const eventType = form.eventType || raw.eventType || raw.event_type || lead.eventType || lead.event_type || '';
const selected = raw.selectedUpgradeLabels || form.selectedUpgrades || raw.selectedUpgrades || [];
const selectedInserts = Array.isArray(raw.selectedInserts) ? raw.selectedInserts
  : (Array.isArray(form.selectedInserts) ? form.selectedInserts : []);
const templateId = raw.template_id || form.templateId || raw.templateId || '';

const leadOut = {
  proposal_ref: uiLead.proposal_ref || lead.referenceNumber || lead.proposal_ref || ('WE.' + Math.floor(1000 + Math.random() * 9000)),
  quote_date: new Date().toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' }) + ' | Quotation valid for 28 days',
};
addIfPresent(leadOut, 'client_name', uiLead.client_name || lead.name || lead.client_name);
addIfPresent(leadOut, 'organisation', uiLead.organisation || lead.companyName || lead.company || lead.organisation);
addIfPresent(leadOut, 'telephone', uiLead.telephone || lead.phone || lead.telephone);
addIfPresent(leadOut, 'email', uiLead.email || lead.email);
addIfPresent(leadOut, 'event_type', eventType);

// Flexible date -> "Date TBC"
const flexibleFlag = lead.eventDateFlexibleBool === true || /(tbc|flexible|yes)/i.test(String(lead.eventDateFlexible || ''));
const eventDateVal = uiLead.event_date || form.eventDate || raw.eventDate || lead.eventDateDisplay || lead.fullEventDate;
if (flexibleFlag) { leadOut.event_date = 'Date TBC'; } else { addIfPresent(leadOut, 'event_date', eventDateVal); }

// Cover = departure -> return. Never embarkation / CRM requestedEventTimes.
const dep = String(raw.departure || form.departure || uiLead.departure || '').trim();
const ret = String(raw.returnTime || form.returnTime || form.return_time || raw.return_time || uiLead.return_time || '').trim();
if (dep && ret) { leadOut.event_timings = dep + ' - ' + ret; }
else {
  const uiTimings = String(uiLead.event_timings || '').trim();
  if (uiTimings) leadOut.event_timings = uiTimings;
}

const guestLow = form.guestCount || raw.guestCount || lead.groupSize;
const guestHigh = form.guestCountHigh || raw.guestCountHigh || '';
const guestRange = (guestHigh && String(guestHigh).trim())
  ? (String(guestLow || '') + '-' + String(guestHigh))
  : (uiLead.guest_range || guestLow || '');
addIfPresent(leadOut, 'guest_range', guestRange);
addIfPresent(leadOut, 'guest_quote_n', String(uiLead.guest_quote_n || guests || lead.groupSizeQuote || form.guestCount || raw.guestCount || ''));

// Form / Quote Sheet fields (UI SoT) — pass through for engine + ops
addIfPresent(leadOut, 'quote_version', form.quoteVersion || raw.quoteVersion || raw.version || uiLead.quote_version);
addIfPresent(leadOut, 'key_items', form.keyItems || raw.keyItems || uiLead.key_items);
addIfPresent(leadOut, 'weekly_period', form.weeklyPeriod || raw.weeklyPeriod || uiLead.weekly_period);
addIfPresent(leadOut, 'day_period', form.dayPeriod || raw.dayPeriod || uiLead.day_period);
addIfPresent(leadOut, 'group_bracket', form.groupBracket || raw.groupBracket || uiLead.group_bracket);
addIfPresent(leadOut, 'no_of_tables', form.noOfTables || raw.noOfTables || uiLead.no_of_tables);

// New business fields passed through cleanly
addIfPresent(leadOut, 'budget', lead.budget || raw.budget || form.budget || uiLead.budget);
addIfPresent(leadOut, 'vessels', lead.vessels || raw.vessels || form.vessels || uiLead.vessels);
addIfPresent(leadOut, 'market', lead.market || raw.market || uiLead.market);
addIfPresent(leadOut, 'source', lead.source || raw.source || uiLead.source);
addIfPresent(leadOut, 'year_of_event', lead.yearOfEvent || raw.yearOfEvent || uiLead.year_of_event);
const repeatVal = lead.repeatClient ?? raw.repeatClient ?? form.repeatClient ?? uiLead.repeat_client;
addIfPresent(leadOut, 'repeat_client', typeof repeatVal === 'boolean' ? (repeatVal ? 'YES' : 'NO') : repeatVal);
addIfPresent(leadOut, 'agent', lead.agent || raw.agent || form.agent);

// Staff / contact defaults (staff insert overrides Katherine). Prefer UI lead overlay.
leadOut.contact_name = uiLead.contact_name || lead.contact_name || 'Katherine Bulaon';
leadOut.contact_title = uiLead.contact_title || lead.contact_title || 'Client Relationship Manager';
leadOut.contact_phone = uiLead.contact_phone || lead.contact_phone || '020 8323 5827';
leadOut.contact_email = uiLead.contact_email || lead.contact_email || 'sales@westendonthethames.com';
// prepared_by = REP name only (gold cover keeps "| Client" + role on template lines)
let preparedBy = uiLead.prepared_by || lead.preparedBy || lead.assignedRep || lead.prepared_by || leadOut.contact_name;
if (preparedBy && String(preparedBy).includes('|')) preparedBy = String(preparedBy).split('|')[0].trim();
addIfPresent(leadOut, 'prepared_by', preparedBy);

const lower = String(eventType).toLowerCase();
const category = raw.category || form.proposalCategory ||
  (lower.includes('wedding') || lower.includes('engagement') ? 'wedding' : (eventType ? 'corporate' : undefined));

const mapped = mapUpgrades(selected);
const out = {
  event_type: eventType,
  ...(category ? { category } : {}),
  ...(templateId ? { template_id: templateId, manual_template: true } : {}),
  lead: leadOut,
  calculations: { guests, package_cost: packageCost, vat, grand_total: grandTotal },
  selectedUpgrades: mapped.length ? mapped : (Array.isArray(raw.selectedUpgrades) ? raw.selectedUpgrades.filter((u) => typeof u === 'string' && u.includes('_')) : []),
  selectedInserts,
  packageWording: raw.packageWording || {},
  menuLinks: raw.menuLinks || form.menuLinks || {},
  mode: raw.mode === 'live' ? 'live' : 'demo',
};
return [{ json: out }];

const raw = $json.body || $json;
if (raw == null || (typeof raw === 'string' && !String(raw).trim())) {
  return [{ json: { ok: false, mode: 'demo', failureEvent: { type: 'FailureEvent', source: 'LeadDataFetch', reason: 'empty or non-JSON request body', httpStatus: 400 } } }];
}
const body = typeof raw === 'object' ? raw : {};
const mode = body.mode === 'live' ? 'live' : 'demo';
return [{ json: { mode, _fetch: true, ok: true } }];

// Flexible header matching -> full Sapphire alias set. No presumption of exact headers.
const mode = ($('Lead Fetch Mode1').first().json.mode) === 'live' ? 'live' : 'demo';

const wanted = [
  ['Client Reference Number', 'referenceNumber'],
  ['Name', 'name'],
  ['Company Name', 'companyName'],
  ['Company Sector', 'companySector'],
  ['Main Contact - Email', 'email'],
  ['Main Contact - Number', 'phone'],
  ['Main Contact - Job Role', 'jobRole'],
  ['Budget', 'budget'],
  ['Repeat Client', 'repeatClient'],
  ['Client Relationship Representative', 'preparedBy'],
  ['Status', 'status'],
  ['Live/Dead', 'liveDead'],
  ['Source', 'source'],
  ['Enquiry Date', 'enquiryDate'],
  ['Event Type', 'eventType'],
  ['Full Event Date', 'fullEventDate'],
  ['Event Date - Flexible', 'eventDateFlexible'],
  ['Requested Event Times', 'requestedEventTimes'],
  ['Group Size', 'groupSize'],
  ['What vessel', 'vessels'],
  ['Market', 'market'],
  ['Best time to call', 'bestTimeToCall'],
  ['Year of Event', 'yearOfEvent'],
];

function norm(s) { return String(s).replace(/\s+/g, ' ').trim().toLowerCase(); }
function pick(row, prefix) {
  const target = norm(prefix);
  for (const key of Object.keys(row)) {
    if (norm(key).startsWith(target)) {
      const v = row[key];
      if (v !== undefined && v !== null && String(v).trim() !== '') return row[key];
    }
  }
  return '';
}
function lowerBound(g) {
  const m = String(g).match(/\d+/);
  return m ? Number(m[0]) : '';
}
function collectProgress(row) {
  const entries = [];
  for (const key of Object.keys(row)) {
    const mm = norm(key).match(/^progress\s+(\d+)$/);
    if (mm) {
      const v = row[key];
      if (v !== undefined && v !== null && String(v).trim() !== '') entries.push([Number(mm[1]), String(row[key]).trim()]);
    }
  }
  entries.sort((a, b) => a[0] - b[0]);
  return entries.map((e) => e[1]).join(' | ');
}
function isFlexible(v) {
  const s = norm(v);
  return s.includes('yes') || s.includes('tbc') || s.includes('flex');
}

const leads = $input.all().map((item) => {
  const row = item.json || {};
  const out = {};
  for (const [prefix, alias] of wanted) out[alias] = pick(row, prefix);
  // derived
  out.assignedRep = out.preparedBy;
  out.groupSizeQuote = lowerBound(out.groupSize);
  out.progressNotes = collectProgress(row);
  out.eventDateFlexibleBool = isFlexible(out.eventDateFlexible);
  out.eventDateDisplay = out.eventDateFlexibleBool ? 'Date TBC' : (out.fullEventDate || '');
  return out;
})
.filter((l) => l.referenceNumber || l.name || l.email) // drop blank / alwaysOutputData placeholder rows
.reverse(); // newest first

return [{ json: { count: leads.length, mode, leads } }];

const body = $input.first().json.body || $input.first().json;
return [{ json: {
  mode: body.mode === 'live' ? 'live' : 'demo',
  referenceNumber: body.referenceNumber || '',
  email: body.email || '',
  leadName: body.leadName || '',
  note: body.note || '',
  tag: body.tag || '',
  createdAt: new Date().toISOString(),
}}];

function cell(row, names) {
  const keys = Object.keys(row || {});
  for (const want of names) {
    if (row[want] !== undefined && row[want] !== null && String(row[want]).trim() !== '') return row[want];
    const hit = keys.find((k) => k.toLowerCase() === String(want).toLowerCase());
    if (hit && row[hit] !== undefined && row[hit] !== null && String(row[hit]).trim() !== '') return row[hit];
  }
  return '';
}

const rows = $input.all().map((i) => i.json || {}).filter((r) => Object.keys(r).length && Object.values(r).some((v) => String(v ?? '').trim() !== ''));
const itemsByLabel = new Map();
const lines = [];
const vessels = new Set();
const periods = { weekly: new Set(), day: new Set(), group: new Set() };
const marginCells = [];
const staffRatios = [];
const cutleryRatios = [];

for (const r of rows) {
  const kind = String(cell(r, ['kind', 'Kind']) || 'rate').toLowerCase();
  const label = String(cell(r, ['label', 'Label']) || '').trim();
  if (kind === 'vessel') {
    if (label) vessels.add(label);
    continue;
  }
  if (kind === 'line') {
    if (!label) continue;
    const section = String(cell(r, ['section', 'Section']) || 'other');
    const multiplier = String(cell(r, ['multiplier', 'Multiplier']) || 'set');
    const id = (section + ':' + label).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '').slice(0, 80);
    lines.push({ id, section, label, multiplier });
    continue;
  }
  if (kind === 'margin') {
    const market = String(cell(r, ['section', 'Section']) || '').trim();
    const month = String(cell(r, ['rateKey', 'Rate Key', 'rate_key']) || '').trim().toUpperCase().slice(0, 3);
    const rate = Number(cell(r, ['rate', 'Rate']));
    if (!label || !/^(JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|OCT|NOV|DEC)$/.test(month) || !Number.isFinite(rate)) continue;
    marginCells.push({ eventService: label, market, month, rate });
    continue;
  }
  if (kind === 'staff_ratio' || kind === 'cutlery_ratio') {
    const rec = {
      label,
      group: String(cell(r, ['section', 'Section']) || '').trim(),
      key: String(cell(r, ['rateKey', 'Rate Key', 'rate_key']) || '').trim(),
      value: Number(cell(r, ['rate', 'Rate'])),
    };
    if (!label || !Number.isFinite(rec.value)) continue;
    (kind === 'staff_ratio' ? staffRatios : cutleryRatios).push(rec);
    continue;
  }
  const rateKey = String(cell(r, ['rateKey', 'Rate Key', 'rate_key']) || '').trim();
  const rate = Number(cell(r, ['rate', 'Rate']));
  if (!label || !rateKey || !Number.isFinite(rate)) continue;
  if (!itemsByLabel.has(label)) itemsByLabel.set(label, { row: itemsByLabel.size + 1, label, rates: {} });
  itemsByLabel.get(label).rates[rateKey] = rate;
  const parts = rateKey.split('|');
  if (parts[0]) vessels.add(parts[0]);
  if (parts[1]) periods.weekly.add(parts[1]);
  if (parts[2]) periods.day.add(parts[2]);
  if (parts[3]) periods.group.add(parts[3]);
}

const marginMap = new Map();
for (const c of marginCells) {
  const k = c.eventService + '||' + c.market;
  if (!marginMap.has(k)) marginMap.set(k, { eventService: c.eventService, market: c.market, months: {} });
  marginMap.get(k).months[c.month] = c.rate;
}
const margins = Array.from(marginMap.values());
const items = Array.from(itemsByLabel.values());
const costMother = items.length ? { source: '_Nexus Catalog', items, ...(margins.length ? { margins } : {}) } : null;

return [{ json: {
  ok: Boolean(costMother),
  source: 'live',
  note: costMother
    ? 'Catalog from Apps Script (_Nexus Catalog).'
    : 'Catalog tab empty — run buildNexusCatalog in Apps Script.',
  failureEvent: costMother ? undefined : { type: 'FailureEvent', source: 'CostRatesFetch', reason: 'Catalog tab empty', httpStatus: 422 },
  costMother,
  lines,
  vessels: Array.from(vessels),
  periods: {
    weekly: Array.from(periods.weekly),
    day: Array.from(periods.day),
    group: Array.from(periods.group),
  },
  margins,
  staffRatios,
  cutleryRatios,
  counts: {
    costMotherItems: items.length,
    lines: lines.length,
    catalogRows: rows.length,
    margins: margins.length,
    staffRatios: staffRatios.length,
    cutleryRatios: cutleryRatios.length,
  },
}}];
